package com.novara.banking.notification;import com.novara.banking.audit.AuditService;import com.novara.banking.identity.CurrentIdentity.FederatedIdentity;import com.novara.banking.shared.DomainException;import org.slf4j.MDC;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;
@Service public class NotificationService{private final JdbcClient jdbc;private final AuditService audit;public NotificationService(JdbcClient j,AuditService a){jdbc=j;audit=a;}
 @Transactional public List<View> list(FederatedIdentity i,int page,int size){long c=customer(i);syncTransfers(c);return jdbc.sql("SELECT public_id,type,title,message,navigation_target,read_at,created_at FROM customer_notifications WHERE customer_id=:c ORDER BY created_at DESC LIMIT :size OFFSET :offset").param("c",c).param("size",size).param("offset",page*size).query(this::map).list();}
 @Transactional public Page page(FederatedIdentity i,int page,int size){long c=customer(i);syncTransfers(c);long total=jdbc.sql("SELECT count(*) FROM customer_notifications WHERE customer_id=:c").param("c",c).query(Long.class).single();return new Page(jdbc.sql("SELECT public_id,type,title,message,navigation_target,read_at,created_at FROM customer_notifications WHERE customer_id=:c ORDER BY created_at DESC,id DESC LIMIT :size OFFSET :offset").param("c",c).param("size",size).param("offset",page*size).query(this::map).list(),page,size,total,(total+size-1)/size);}
 @Transactional public long unread(FederatedIdentity i){long c=customer(i);syncTransfers(c);return jdbc.sql("SELECT count(*) FROM customer_notifications WHERE customer_id=:c AND read_at IS NULL").param("c",c).query(Long.class).single();}
 @Transactional public void read(FederatedIdentity i,UUID id){int n=jdbc.sql("UPDATE customer_notifications SET read_at=COALESCE(read_at,now()) WHERE public_id=:id AND customer_id=:c").param("id",id).param("c",customer(i)).update();if(n!=1)throw missing();audit.record(i.subject(),"NOTIFICATION_READ","NOTIFICATION",id,"SUCCESS",MDC.get("correlationId"),"{}");}
 @Transactional public void readAll(FederatedIdentity i){jdbc.sql("UPDATE customer_notifications SET read_at=now() WHERE customer_id=:c AND read_at IS NULL").param("c",customer(i)).update();}
 public Preferences preferences(FederatedIdentity i){long c=customer(i);jdbc.sql("INSERT INTO notification_preferences(customer_id) VALUES(:c) ON CONFLICT DO NOTHING").param("c",c).update();return jdbc.sql("SELECT transaction_activity,statements,deposits,loan_applications,service_requests,version FROM notification_preferences WHERE customer_id=:c").param("c",c).query((r,n)->new Preferences(r.getBoolean(1),r.getBoolean(2),r.getBoolean(3),r.getBoolean(4),r.getBoolean(5),r.getLong(6),true)).single();}
 @Transactional public Preferences preferences(FederatedIdentity i,Preferences p){long c=customer(i);preferences(i);int n=jdbc.sql("UPDATE notification_preferences SET transaction_activity=:t,statements=:s,deposits=:d,loan_applications=:l,service_requests=:r,version=version+1,updated_at=now() WHERE customer_id=:c AND version=:v").param("t",p.transactionActivity()).param("s",p.statements()).param("d",p.deposits()).param("l",p.loanApplications()).param("r",p.serviceRequests()).param("c",c).param("v",p.version()).update();if(n!=1)throw new DomainException(HttpStatus.CONFLICT,"PREFERENCES_CHANGED","Preferences changed. Refresh and try again.");return preferences(i);}
 private void syncTransfers(long c){jdbc.sql("""
  INSERT INTO customer_notifications(customer_id,type,title,message,navigation_target,source_event_id)
  SELECT :c,'TRANSACTION','Transfer completed','A transfer was posted successfully.','/payments/history',o.event_id
  FROM outbox_events o JOIN transfers t ON t.public_id=o.aggregate_id JOIN bank_accounts a ON a.id=t.source_account_id
  JOIN account_owners own ON own.account_id=a.id
  WHERE o.event_type='InternalTransferCompleted' AND own.customer_id=:c
    AND COALESCE((SELECT p.transaction_activity FROM notification_preferences p WHERE p.customer_id=:c),true)
  ON CONFLICT DO NOTHING
  """).param("c",c).update();}
 private long customer(FederatedIdentity i){return jdbc.sql("SELECT id FROM customers WHERE identity_issuer=:issuer AND identity_subject=:subject AND status='ACTIVE'").param("issuer",i.issuer()).param("subject",i.subject()).query(Long.class).optional().orElseThrow(this::missing);}
 private View map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new View(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getTimestamp(6)==null?null:r.getTimestamp(6).toInstant(),r.getTimestamp(7).toInstant());}private DomainException missing(){return new DomainException(HttpStatus.NOT_FOUND,"NOTIFICATION_NOT_FOUND","The notification was not found.");}
 public record View(UUID id,String type,String title,String message,String navigationTarget,Instant readAt,Instant createdAt){}public record Page(List<View> items,int page,int size,long totalElements,long totalPages){}public record Preferences(boolean transactionActivity,boolean statements,boolean deposits,boolean loanApplications,boolean serviceRequests,long version,boolean mandatorySecurityAlerts){}
}
